interface Notifier { notify(msg: string): void }
class ConsoleNotifier implements Notifier { notify(msg: string) { console.log(msg) } }
class NullNotifier implements Notifier { notify(msg: string) { /* no-op */ } }
function getNotifier(enabled: boolean): Notifier {
  return enabled ? new ConsoleNotifier() : new NullNotifier();
}
const notifier = getNotifier(false);
notifier.notify('Order placed');

